export const styleVersion = (style, patch = {}) => {
  const base = defaultStyleDna(style);
  const locked = new Set(base.lockedProperties || []);
  const next = structuredClone(base);
  Object.entries(patch).forEach(([key, value]) => { if (!locked.has(key)) next[key] = value; });
  next.id = base.id; next.parentStyleId = base.parentStyleId || base.id; next.version = base.version + 1; next.versionId = `style-version-${idPart()}`; next.updatedAt = now();
  return defaultStyleDna(next);
};

const merge = (base, patch) => {
  if (!patch || typeof patch !== "object") return structuredClone(base);
  const result = structuredClone(base);
  Object.entries(patch).forEach(([key, value]) => {
    if (Array.isArray(value)) result[key] = value.slice();
    else if (value && typeof value === "object" && result[key] && typeof result[key] === "object" && !Array.isArray(result[key])) result[key] = merge(result[key], value);
    else result[key] = value;
  });
  return result;
};

export const createVisualDirectionState = () => ({ schemaVersion: VISUAL_DIRECTION_SCHEMA_VERSION, projectStyle: null, sceneOverrides: {}, shotOverrides: {}, favorites: [], recentlyUsed: [], styleStrength: "balanced", styleHistory: {} });

export const migrateVisualDirection = (project, legacyStyles = []) => {
  const state = project.visualDirection && typeof project.visualDirection === "object" ? { ...createVisualDirectionState(), ...project.visualDirection } : createVisualDirectionState();
  const projectStyles = Array.isArray(project.styleDnas) ? project.styleDnas.map((style) => defaultStyleDna(style)) : [];
  const legacyStyle = legacyStyles.find((style) => style.name === project.style);
  if (!state.projectStyle && project.style) {
    const matched = projectStyles.find((style) => style.name === project.style) || (legacyStyle ? legacyStyleToDna(legacyStyle) : null);
    if (matched) state.projectStyle = { styleId: matched.id, versionId: matched.versionId, snapshot: matched };
  }
  (project.scenes || []).forEach((scene) => {
    if (!scene?.appliedStyleDnaId || state.sceneOverrides?.[scene.id]) return;
    const style = projectStyles.find((candidate) => candidate.id === scene.appliedStyleDnaId);
    if (style) state.sceneOverrides[scene.id] = { styleId: style.id, versionId: style.versionId, snapshot: style, patch: {} };
  });
  state.styleHistory = state.styleHistory && typeof state.styleHistory === "object" ? state.styleHistory : {};
  state.schemaVersion = VISUAL_DIRECTION_SCHEMA_VERSION;
  return state;
};

export const styleHistoryFor = (state, styleId) => {
  const entries = state?.styleHistory?.[styleId];
  return Array.isArray(entries) ? entries.map((entry) => defaultStyleDna(entry)) : [];
};

export const appendStyleHistory = (state, style) => {
  if (!state || !style?.id) return;
  state.styleHistory = state.styleHistory && typeof state.styleHistory === "object" ? state.styleHistory : {};
  const versions = styleHistoryFor(state, style.id);
  if (!versions.some((entry) => entry.versionId === style.versionId)) versions.unshift(defaultStyleDna(style));
  state.styleHistory[style.id] = versions.slice(0, 40);
};

export const resolveVisualDirection = (project, { scene, shot, builtIns = [] } = {}) => {
  const state = project.visualDirection || createVisualDirectionState();
  const lookup = (binding) => binding?.snapshot || [...(project.styleDnas || []), ...builtIns].find((style) => style.id === binding?.styleId) || null;
  const sources = [];
  let resolved = null;
  const apply = (binding, scope) => { const style = lookup(binding); if (!style) return; resolved = merge(resolved || defaultStyleDna(style), binding.patch || {}); sources.push({ scope, styleId: style.id, versionId: binding.versionId || style.versionId, name: style.name }); };
  apply(state.projectStyle, "project");
  if (scene) apply(state.sceneOverrides?.[scene.id], "scene");
  if (shot) apply(state.shotOverrides?.[shot.id], "shot");
  return { style: resolved ? defaultStyleDna(resolved) : null, sources, strength: STYLE_STRENGTHS[state.styleStrength] || STYLE_STRENGTHS.balanced };
};

// context lets a caller pull the DNA's asset-specific guidance too — the
// schema carries dedicated promptBlocks.character/.environment/.prop text
// plus richer characters/environments/props sub-objects (facial design and
// identity-consistency rules for a character, architecture and set-dressing
// rules for an environment, material and scale rules for a prop) that a
// generic image/video prompt never surfaced. Optional and purely additive —
// every existing 2-arg call site (shots have no single "kind" of asset)
// keeps behaving exactly as before.
const CONTEXT_FIELDS = {
  character: (style) => [style.characters?.anatomy, style.characters?.proportions, style.characters?.facialDesign, style.characters?.eyes, style.characters?.hair, style.characters?.wardrobe, style.characters?.texture, style.characters?.actingStyle, style.characters?.microAnimation?.join(", "), style.characters?.identityConsistencyRules?.join(", ")],
  environment: (style) => [style.environments?.architecture, style.environments?.terrain, style.environments?.atmosphericPerspective, style.environments?.worldDensity, style.environments?.setDressingRules?.join(", ")],
  prop: (style) => [style.props?.designLanguage, style.props?.materialRules?.join(", "), style.props?.scaleRules?.join(", ")]
};
// `strength` (a STYLE_STRENGTHS value, 0.3–1) used to be resolved and carried
// around as metadata (visualDirectionMetadata(), generation.visualDirection)
// but never actually reached the prompt text this function builds — the
// Style Strength control compiled correctly but had no effect on any
// generation, subtle and signature produced byte-identical prompts. That's
// the "application of the style is very minimal" gap: nothing here ever
// pushed back against a subject description (e.g. an established "3D"
// character's own appearance text) that pulls toward a different rendering
// than the applied style.
export const stylePromptBlocks = (style, kind = "image", context = "", strength = STYLE_STRENGTHS.balanced) => {
  if (!style) return { positive: [], negative: [] };
  const core = [style.promptBlocks?.universal, style.promptBlocks?.[kind], style.visualLanguage?.shapeLanguage, style.lighting?.approach];
  const extended = [style.camera?.shotLanguage?.join(", "), style.materials?.primaryMaterials?.join(", "), style.continuityRules?.join(", "), context && style.promptBlocks?.[context], ...(context && CONTEXT_FIELDS[context] ? CONTEXT_FIELDS[context](style) : [])];
  // Subtle: core language only, no directive — closest to "just a light
  // influence". Balanced: today's original full block set, unchanged.
  // Strong/Signature: full set plus an explicit directive that escalates
  // with strength, since text-to-image models otherwise happily blend a
  // style suggestion with whatever a photorealistic/3D-coded subject
  // description implies instead of one overriding the other.
  const directive = strength >= 1
    ? "This visual style is the authoritative rendering language for this shot and overrides any conflicting medium, rendering, or realism implied elsewhere in this brief — including an existing character, set, or prop described or previously rendered in a different medium (e.g. photorealistic or 3D-rendered). Do not blend renderers; commit fully to the style below."
    : strength >= STYLE_STRENGTHS.strong
      ? "Render fully in the visual style below, even where it conflicts with a photorealistic or 3D-rendered description elsewhere in this brief."
      : strength >= STYLE_STRENGTHS.balanced
        ? "Apply the visual style below as this shot's rendering language."
        : "";
  const positive = strength < STYLE_STRENGTHS.balanced ? core.filter(Boolean) : [directive, ...core, ...extended, ...(strength >= 1 ? core.slice(0, 2) : [])].filter(Boolean);
  const negative = [style.promptBlocks?.negative, ...(style.forbiddenElements || []), ...(kind === "video" ? style.animation?.forbiddenMotion || [] : [])];
  // Only for a style that isn't itself meant to look photoreal/3D — pushing
  // "no photorealism" on a style that wants exactly that would fight itself.
  if (strength >= STYLE_STRENGTHS.strong && (style.visualLanguage?.levelOfRealism ?? 55) < 50) {
    negative.push("photorealistic rendering", "3D CGI shading and lighting", "any rendering medium other than the style specified above");
  }
  return { positive: [...new Set(positive)], negative: [...new Set(negative.filter(Boolean))] };
};

export const blendStyles = (sources) => {
  const active = (sources || []).filter((source) => source?.style && Number(source.weight) > 0).slice(0, 4);
  if (active.length < 2) throw new Error("Choose at least two styles to create a mix.");
  const total = active.reduce((sum, source) => sum + Number(source.weight), 0);
  const winner = [...active].sort((a, b) => Number(b.weight) - Number(a.weight))[0].style;
  const result = defaultStyleDna({ ...winner, id: `style-${idPart()}`, versionId: `style-version-${idPart()}`, name: "Untitled Style Mix", source: "remixed", parentStyleId: winner.id, createdAt: now(), updatedAt: now() });
  const weightedText = (reader) => active.sort((a, b) => b.weight - a.weight).map((source) => reader(source.style)).filter(Boolean).slice(0, 3).join("; ");
  result.promptBlocks.universal = weightedText((style) => style.promptBlocks?.universal);
  result.promptBlocks.negative = [...new Set(active.flatMap((source) => [source.style.promptBlocks?.negative, ...(source.style.forbiddenElements || [])]).filter(Boolean))].join(", ");
  result.color.primaryColors = [...new Set(active.flatMap((source) => source.style.color?.primaryColors || []))].slice(0, 6);
  result.materials.primaryMaterials = [...new Set(active.flatMap((source) => source.style.materials?.primaryMaterials || []))].slice(0, 6);
  result.continuityRules = [...new Set(active.flatMap((source) => source.style.continuityRules || []))];
  result.forbiddenElements = [...new Set(active.flatMap((source) => source.style.forbiddenElements || []))];
  result.description = `Structured mix of ${active.map((source) => `${source.style.name} ${Math.round((source.weight / total) * 100)}%`).join(", ")}.`;
  return result;
};
